using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — fixes for EF Core 9 breaking changes:
// 1. Discriminator property renamed from "Discriminator" to "$type" — preserve old name
// 2. id property no longer embeds discriminator — preserve old format
// 3. Sync I/O now throws — use async methods only

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Existing documents use "Discriminator" — keep the old property name
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Existing documents have id format "Session|<key>" — preserve it
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

// Fix 3: Example showing sync → async migration (sync I/O now throws)
class CosmosQueryService
{
    // BEFORE (EF Core 8 — sync was allowed):
    //   var sessions = db.Sessions.ToList();
    //   db.SaveChanges();

    // AFTER (EF Core 9 — must use async):
    async Task<List<Session>> GetSessionsAsync(CosmosDbContext db)
    {
        return await db.Sessions.ToListAsync();
    }

    async Task SaveAsync(CosmosDbContext db)
    {
        await db.SaveChangesAsync();
    }
}

